import axios from 'axios';

const API_BASE_URL = 'https://localhost:7285/api'; // Web API'nizin HTTPS URL'si

const api = {
    // Store1 için API çağrıları
    store1: {
        getAllStock: async () => {
            try {
                const response = await axios.get(`${API_BASE_URL}/Store1/StockGetAll`);
                return response.data;
            } catch (error) {
                console.error('Store1 stok verisi alınırken hata oluştu:', error);
                throw error;
            }
        },
        createStock: async (stockData) => {
            try {
                const response = await axios.post(`${API_BASE_URL}/Store1/StockCreate`, stockData);
                return response.data;
            } catch (error) {
                console.error('Store1 stok oluşturulurken hata oluştu:', error);
                throw error;
            }
        },
        updateStock: async (stockData) => {
            try {
                const response = await axios.put(`${API_BASE_URL}/Store1/StockUpdate`, stockData);
                return response.data;
            } catch (error) {
                console.error('Store1 stok güncellenirken hata oluştu:', error);
                throw error;
            }
        },
        createSale: async (saleData) => {
            try {
                const response = await axios.post(`${API_BASE_URL}/Store1/SaleCreate`, saleData);
                return response.data;
            } catch (error) {
                console.error('Store1 satış oluşturulurken hata oluştu:', error);
                throw error;
            }
        },
        createReturn: async (returnData) => {
            try {
                const response = await axios.post(`${API_BASE_URL}/Store1/ReturnCreate`, returnData);
                return response.data;
            } catch (error) {
                console.error('Store1 iade oluşturulurken hata oluştu:', error);
                throw error;
            }
        }
    },

    // Store2 için API çağrıları
    store2: {
        getAllStock: async () => {
            try {
                const response = await axios.get(`${API_BASE_URL}/Store2/StockGetAll`);
                return response.data;
            } catch (error) {
                console.error('Store2 stok verisi alınırken hata oluştu:', error);
                throw error;
            }
        },
        createStock: async (stockData) => {
            try {
                const response = await axios.post(`${API_BASE_URL}/Store2/StockCreate`, stockData);
                return response.data;
            } catch (error) {
                console.error('Store2 stok oluşturulurken hata oluştu:', error);
                throw error;
            }
        },
        updateStock: async (stockData) => {
            try {
                const response = await axios.put(`${API_BASE_URL}/Store2/StockUpdate`, stockData);
                return response.data;
            } catch (error) {
                console.error('Store2 stok güncellenirken hata oluştu:', error);
                throw error;
            }
        },
        createSale: async (saleData) => {
            try {
                const response = await axios.post(`${API_BASE_URL}/Store2/SaleCreate`, saleData);
                return response.data;
            } catch (error) {
                console.error('Store2 satış oluşturulurken hata oluştu:', error);
                throw error;
            }
        },
        createReturn: async (returnData) => {
            try {
                const response = await axios.post(`${API_BASE_URL}/Store2/ReturnCreate`, returnData);
                return response.data;
            } catch (error) {
                console.error('Store2 iade oluşturulurken hata oluştu:', error);
                throw error;
            }
        }
    }
};

export default api;
